refentry.refsect1:
  &reftitle.description;

   truearray_multisort
   arrayarray1
   mixedarray1_sort_orderSORT_ASC
   mixedarray1_sort_flagsSORT_REGULAR
   mixedrest


array_multisort लाई एकैपटक धेरै arrays, वा एक वा बढी dimensions अनुसार एउटा multi-dimensional array लाई sort गर्न प्रयोग गर्न सकिन्छ।

Associative (string) keys कायम राखिनेछ, तर numeric keys लाई भने re-index गरिनेछ।
  &note.sort-unstable;
  &note.reset-index;

&reftitle.errors;
यदि कुनै अज्ञात sort flag दिइयो भने, वा सबै arrays को size एउटै छैन भने एउटा ValueError throw गर्दछ।
यदि कुनै argument न त array न त sort flag हो भने, वा एउटै array का लागि एकै प्रकारको sort flag दुई पटक दिइयो भने एउटा TypeError throw गर्दछ।

&reftitle.changelog;





    &Version;
    &Description;





    8.5.0
    return type अब &true; भएको छ; पहिले, यो bool थियो।



    8.0.0
    अब अमान्य arguments का लागि ValueError वा TypeError throw गर्दछ। पहिले, E_WARNING raise गरिन्थ्यो र &false; return गरिन्थ्यो।

  &reftitle.examples;



    धेरै arrays sort गर्ने


<?php
$ar1 = array(10, 100, 100, 0);
$ar2 = array(1, 3, 2, 4);
array_multisort($ar1, $ar2);

var_dump($ar1);
var_dump($ar2);
?>



यस उदाहरणमा, sort गरिसकेपछि, पहिलो array मा 0, 10, 100, 100 हुनेछ। दोस्रो array मा 4, 1, 2, 3 हुनेछ। दोस्रो array का ती entries, जुन पहिलो array का समान entries (100 र 100) सँग मेल खान्छन्, ती पनि sort गरिएका थिए।


array(4) {
  [0]=> int(0)
  [1]=> int(10)
  [2]=> int(100)
  [3]=> int(100)
}
array(4) {
  [0]=> int(4)
  [1]=> int(1)
  [2]=> int(2)
  [3]=> int(3)
}







    multi-dimensional array sort गर्ने


<?php
$ar = array(
       array("10", 11, 100, 100, "a"),
       array(   1,  2, "2",   3,   1)
      );
array_multisort($ar[0], SORT_ASC, SORT_STRING,
                $ar[1], SORT_NUMERIC, SORT_DESC);
var_dump($ar);
?>



यस उदाहरणमा, sort गरिसकेपछि, पहिलो array "10", 100, 100, 11, "a" मा रूपान्तरण हुनेछ (यसलाई ascending order मा strings का रूपमा sort गरिएको थियो)। दोस्रोमा 1, 3, "2", 2, 1 हुनेछ (descending order मा numbers का रूपमा sort गरिएको)।


array(2) {
  [0]=> array(5) {
    [0]=> string(2) "10"
    [1]=> int(100)
    [2]=> int(100)
    [3]=> int(11)
    [4]=> string(1) "a"
  }
  [1]=> array(5) {
    [0]=> int(1)
    [1]=> int(3)
    [2]=> string(1) "2"
    [3]=> int(2)
    [4]=> int(1)
  }
}







    database results sort गर्ने

यस उदाहरणका लागि, each element, जुन data array मा छ, त्यसले table को एउटा row लाई जनाउँछ। यस type को dataset, database records को विशिष्ट उदाहरण हो।

उदाहरण data:


volume | edition
-------+--------
    67 |       2
    86 |       1
    85 |       6
    98 |       2
    86 |       6
    67 |       7



यो data एउटा array को रूपमा छ, जसलाई data भनिन्छ। उदाहरणका लागि, यो प्रायः mysqli_fetch_assoc सँग loop गरेर प्राप्त गरिन्छ।

यस उदाहरणमा, हामी volume descending, र edition ascending क्रममा order गर्नेछौँ।

हामीसँग row हरूको एउटा array छ, तर array_multisort लाई column हरूको एउटा array चाहिन्छ, त्यसैले column हरू प्राप्त गर्न हामी तलको code प्रयोग गर्छौँ, र त्यसपछि sorting गर्छौँ।


<?php
// The data as created by looping over mysqli_fetch_assoc:
$data[] = array('volume' => 67, 'edition' => 2);
$data[] = array('volume' => 86, 'edition' => 1);
$data[] = array('volume' => 85, 'edition' => 6);
$data[] = array('volume' => 98, 'edition' => 2);
$data[] = array('volume' => 86, 'edition' => 6);
$data[] = array('volume' => 67, 'edition' => 7);

// Obtain a list of columns
foreach ($data as $key => $row) {
    $volume[$key]  = $row['volume'];
    $edition[$key] = $row['edition'];
}

// You can use array_column() instead of the above code
$volume  = array_column($data, 'volume');
$edition = array_column($data, 'edition');

// Sort the data with volume descending, edition ascending
// Add $data as the last parameter, to sort by the common key
array_multisort($volume, SORT_DESC, $edition, SORT_ASC, $data);

// Loop over the data and output the sorted values for each column
echo 'volume | edition', PHP_EOL;
echo '-------+--------', PHP_EOL;
for ($i = 0; $i < count($data); $i++) {
     printf("%6d | %7d\n", $volume[$i], $edition[$i]);
}
?>



यो dataset अब sort भइसकेको छ, र यस्तो देखिनेछ:


volume | edition
-------+--------
    98 |       2
    86 |       1
    86 |       6
    85 |       6
    67 |       2
    67 |       7







    Case-insensitive sort गर्ने

SORT_STRING र SORT_REGULAR दुवै case sensitive हुन्, capital letter बाट सुरु हुने strings, lowercase letter बाट सुरु हुने strings भन्दा अगाडि आउनेछन्।

case insensitive sort गर्नका लागि, मूल array को lowercase copy द्वारा sorting order निर्धारित हुने बनाउनुहोस्।


<?php
$array = array('Alpha', 'atomic', 'Beta', 'bank');
$array_lowercase = array_map('strtolower', $array);

array_multisort($array_lowercase, SORT_ASC, SORT_STRING, $array);

print_r($array);
?>


    &example.outputs;


Array
(
    [0] => Alpha
    [1] => atomic
    [2] => bank
    [3] => Beta
)
